<template><el-container class="app-shell"><el-aside width="230px"><div class="brand">TK WORKSPACE<span>跨境运营工作台</span></div><el-menu router :default-active="$route.path"><el-menu-item index="/">运营首页</el-menu-item><el-menu-item index="/workbench/today">今日工作台</el-menu-item><el-menu-item index="/ads">广告计划中心</el-menu-item><el-menu-item index="/content/dashboard">内容生产中心</el-menu-item><el-sub-menu index="content-assets"><template #title>内容资产</template><el-menu-item index="/content/markets">市场库</el-menu-item><el-menu-item index="/content/products">产品库</el-menu-item><el-menu-item index="/content/assets">素材库</el-menu-item><el-menu-item index="/content/scripts">口播脚本</el-menu-item><el-menu-item index="/content/templates">内容模板</el-menu-item><el-menu-item index="/content/mix-projects">混剪方案</el-menu-item><el-menu-item index="/content/videos">视频作品</el-menu-item><el-menu-item index="/content/assistant">创作助手</el-menu-item></el-sub-menu><el-menu-item index="/operations">运营记录</el-menu-item></el-menu></el-aside><el-container><el-header><div><span class="eyebrow">TK CROSS-BORDER WORKSPACE</span><h2>{{ pageTitle }}</h2></div><el-button v-if="showAddAsset" type="primary" @click="$router.push('/content/assets')">新增素材</el-button></el-header><el-main><router-view/></el-main></el-container></el-container></template>
<script setup lang="ts">import {computed} from 'vue'; import {useRoute} from 'vue-router'; const route=useRoute(); const titles:any={markets:'市场库',products:'产品库',assets:'素材库',scripts:'口播脚本',templates:'内容模板','mix-projects':'混剪方案',videos:'视频作品',assistant:'创作助手'}; const showAddAsset=computed(()=>route.path==='/assets'||route.path==='/content/assets'); const pageTitle=computed(()=>route.path==='/'?'运营首页':route.path==='/workbench/today'?'今日工作台':route.path==='/ads'?'广告计划中心':route.path==='/operations'?'运营记录':route.path==='/content/dashboard'?'内容生产中心':route.path.startsWith('/mix-projects/')||route.path.includes('/mix-projects/')?'混剪方案':titles[String(route.params.resource)]||'内容生产中心')</script>
